--- a/src/truetype/ttvarc.c
+++ b/src/truetype/ttvarc.c
@@ -2044,16 +2044,13 @@
       control = *p++;
       cnt     = ( control & 0x3F ) + 1;

-      if ( cnt > num_indices - i )
-        cnt = num_indices - i;
-
       if ( ( control & 0xC0 ) == 0xC0 )
       {
         /* 32-bit values */
         if ( p + 4 * cnt > tuple_limit )
           return FT_THROW( Invalid_Table );

-        for ( j = 0; j < cnt && i < num_indices; j++, i++ )
+        for ( j = 0; j < cnt; j++, i++ )
         {
           indices[i] = ( (FT_UInt)p[0] << 24 ) |
                        ( (FT_UInt)p[1] << 16 ) |
@@ -2065,7 +2062,7 @@
       else if ( control & 0x80 )
       {
         /* zeros */
-        for ( j = 0; j < cnt && i < num_indices; j++, i++ )
+        for ( j = 0; j < cnt; j++, i++ )
           indices[i] = 0;
       }
       else if ( control & 0x40 )
@@ -2074,7 +2071,7 @@
         if ( p + 2 * cnt > tuple_limit )
           return FT_THROW( Invalid_Table );

-        for ( j = 0; j < cnt && i < num_indices; j++, i++ )
+        for ( j = 0; j < cnt; j++, i++ )
         {
           indices[i] = ( (FT_UInt)p[0] << 8 ) |
                          (FT_UInt)p[1];
@@ -2087,7 +2084,7 @@
         if ( p + cnt > tuple_limit )
           return FT_THROW( Invalid_Table );

-        for ( j = 0; j < cnt && i < num_indices; j++, i++ )
+        for ( j = 0; j < cnt; j++, i++ )
           indices[i] = *p++;
       }
     }
